// Skills as the client sees them. The server's catalog (GET /progression/catalog, `skills`) is the source of every
// number and rule; these helpers only order skills, check a bar before it is sent and build combat commands.
// They mirror DefaultLoadout and ValidateLoadout in backend/internal/game/skills.go, which stay authoritative.

export type SkillTarget = "enemy" | "all_enemies" | "self" | "ally" | "party" | "fallen";

export type Skill = {
  id: string;
  classId?: string;
  name: string;
  description: string;
  /** Exact rule text generated by the server from the skill's effects. */
  rules: string;
  icon: string;
  tone: "strike" | "guard" | "control" | "support" | string;
  target: SkillTarget;
  cooldown?: number;
  masteryLevel: number;
  basic?: boolean;
  elemental?: boolean;
  effects?: { kind: string; amount?: number; stat?: string; rounds?: number; scope?: string }[];
  /** Rule text at each rank, I first (the server's MaxSkillRank entries). */
  rankRules?: string[];
};

/** The highest rank a skill can reach in one run (MaxSkillRank on the server). */
export const MAX_SKILL_RANK = 5;
export const ROMAN = ["", "I", "II", "III", "IV", "V"];

/** A player's rank in a skill this run: 1 until they spend a skill point on it. */
export function skillRank(ranks: Record<string, number> | undefined, skillId: string): number {
  return Math.max(1, Math.min(MAX_SKILL_RANK, ranks?.[skillId] ?? 1));
}

export const SKILL_DEFEND = "skill.defend";
export const MAX_LOADOUT = 6;
/** A cooldown at or above this is "once a fight": every skill is ready again when a fight is won. */
export const ONCE_PER_FIGHT = 99;

/** The skills a class can learn in bar order: its starting skills, Defend, then the rest by mastery. */
export function skillsForClass(catalog: readonly Skill[], classId: string): Skill[] {
  const own = catalog.filter(skill => skill.classId === classId);
  const defend = catalog.find(skill => skill.id === SKILL_DEFEND);
  const first = own.filter(skill => skill.masteryLevel <= 1);
  const rest = own.filter(skill => skill.masteryLevel > 1);
  return [...first, ...(defend ? [defend] : []), ...rest];
}

export function defaultLoadout(catalog: readonly Skill[], classId: string, mastery: number): string[] {
  return skillsForClass(catalog, classId).filter(skill => skill.masteryLevel <= mastery).slice(0, MAX_LOADOUT).map(skill => skill.id);
}

/** Why a bar would be refused, or "" when the server will accept it. */
export function loadoutProblem(catalog: readonly Skill[], classId: string, mastery: number, ids: readonly string[]): string {
  if (ids.length === 0) return "Choose at least one skill.";
  if (ids.length > MAX_LOADOUT) return `A bar holds at most ${MAX_LOADOUT} skills.`;
  if (new Set(ids).size !== ids.length) return "Each skill can only be on the bar once.";
  const known = new Map(skillsForClass(catalog, classId).map(skill => [skill.id, skill]));
  let ready = false;
  for (const id of ids) {
    const skill = known.get(id);
    if (!skill) return "That skill belongs to another class.";
    if (skill.masteryLevel > mastery) return `${skill.name} unlocks at mastery ${skill.masteryLevel}.`;
    ready ||= !skill.cooldown;
  }
  return ready ? "" : "Bring at least one skill with no cooldown, so there is always something to do.";
}

/** A remembered bar if the server would still accept it, else the default one. */
export function usableLoadout(catalog: readonly Skill[], classId: string, mastery: number, remembered?: readonly string[]): string[] {
  if (remembered && !loadoutProblem(catalog, classId, mastery, remembered)) return [...remembered];
  return defaultLoadout(catalog, classId, mastery);
}

/** Whether a skill waits for the player to pick a target before it is sent. */
export function needsTarget(target: SkillTarget) {
  return target === "enemy" || target === "fallen";
}

export function skillCommand(skill: Pick<Skill, "id">, round: number, targetId = "") {
  return { type: "combat", round, action: "skill", skill: skill.id, ...(targetId ? { targetId } : {}) };
}

/** Rounds until a skill can be used again (0 when ready). */
export function cooldownLeft(cooldowns: Record<string, number> | undefined, skillId: string) {
  return Math.max(0, cooldowns?.[skillId] ?? 0);
}

export function cooldownLabel(skill: Pick<Skill, "cooldown">) {
  const rounds = skill.cooldown ?? 0;
  if (!rounds) return "No cooldown";
  if (rounds >= ONCE_PER_FIGHT) return "Once a fight";
  return `${rounds}-round cooldown`;
}
